package com.bank.genderratio;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class RatioDemo {
    private static final Logger log = Logger.getLogger("GenderRatio");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", Gender.MALE),
            new Employee("Amit", "IT", Gender.MALE),
            new Employee("Neha", "IT", Gender.FEMALE),    // IT: 2M / 1F = 2.0
            new Employee("Priya", "Sales", Gender.FEMALE));// Sales: 0M / 1F = 0.0
        GenderRatioService service = new GenderRatioService();

        Map<String, Double> ratios = service.ratioByDepartment(staff);
        ratios.forEach((dept, r) -> log.info(() -> dept + " M:F ratio = " + r));
    }
}

// ─── Would be in model/Gender.java ───
enum Gender { MALE, FEMALE }

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final Gender gender;
    Employee(String name, String department, Gender gender) {
        this.name = name; this.department = department; this.gender = gender;
    }
    String getDepartment() { return department; }
    Gender getGender() { return gender; }
}

// ─── Would be in service/GenderRatioService.java ───
class GenderRatioService {
    Map<String, Double> ratioByDepartment(List<Employee> staff) {
        Map<String, Map<Boolean, Long>> counts = staff.stream()
            .filter(e -> e.getGender() != null && e.getDepartment() != null)
            .collect(groupingBy(Employee::getDepartment,
                partitioningBy(e -> e.getGender() == Gender.MALE, counting())));

        Map<String, Double> ratios = new LinkedHashMap<>();
        counts.forEach((dept, m) -> {
            long males = m.get(true);
            long females = m.get(false);
            // guard divide-by-zero: no females → undefined ratio sentinel
            double ratio = females == 0 ? Double.POSITIVE_INFINITY
                : (double) males / females;
            ratios.put(dept, ratio);
        });
        return ratios;
    }
}
